# Extract publication year from details
import re
books = conn.execute("SELECT book_id, details FROM books_info").fetchall()

def extract_year(text):
    if not text:
        return None
    # Look for year pattern (4-digit number 19xx or 20xx)
    m = re.search(r'\b(19\d{2}|20\d{2})\b', text)
    if m:
        return int(m.group(1))
    return None

book_years = {}
for bid, det in books:
    y = extract_year(det)
    if y:
        book_years[bid] = y

print(len(book_years), "books with years")
print(list(book_years.items())[:5])

# Inspect 12 books without years
for bid, det in books:
    if bid not in book_years:
        print(bid, "->", det[:200] if det else None)

def extract_year(text):
    if not text:
        return None
    # Look for any 4-digit year
    m = re.search(r'\b(1[0-9]{3}|20\d{2})\b', text)
    if m:
        return int(m.group(1))
    return None

book_years = {}
for bid, det in books:
    y = extract_year(det)
    if y:
        book_years[bid] = y
print(len(book_years))
print(book_years.get('bookid_164'))

